WITH lines AS (SELECT id, plan, effective_from, element FROM price_tiers LATERAL VIEW OUTER EXPLODE(tier_prices) li AS element) SELECT DATE_TRUNC('YEAR', effective_from) AS year_start, ROUND(SUM(element) / NULLIF(COUNT(CASE WHEN plan = 'enterprise' THEN 1 END), 0), 2) AS element_per_enterprise, SUM(CASE WHEN plan = 'pro' THEN element ELSE 0 END) AS pro_element FROM lines GROUP BY DATE_TRUNC('YEAR', effective_from) ORDER BY pro_element DESC
